def choose_move(observation):
    def sg(key, default=0):
        v = observation.get(key, default)
        return default if v is None else v

    def pos(key):
        v = observation.get(key)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def step_toward(a, b):
        if b is None:
            return [0, 0]
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (1 if bx > ax else -1)
        dy = 0 if by == ay else (1 if by > ay else -1)
        return [dx, dy]

    def dist2(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_target(cands, cur, maximize=False):
        best = None
        best_score = None
        for c in cands:
            if not (isinstance(c, (list, tuple)) and len(c) >= 2):
                continue
            p = (c[0], c[1])
            s = dist2(cur, p)
            if maximize:
                s = -s
            if best is None or s < best_score:
                best = p
                best_score = s
        return best

    env = observation.get("environment_name", "resource_collection")
    sx_sy = pos("self_position")
    if sx_sy is None:
        return [0, 0]
    sx, sy = sx_sy
    ox_oy = pos("opponent_position")

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            if ox_oy is not None:
                return step_toward((sx, sy), ox_oy)
            return [0, 0]
        grid_w = sg("grid_width", 0)
        grid_h = sg("grid_height", 0)
        corners = []
        if grid_w and grid_h:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        if ox_oy is not None and corners:
            target = best_target(corners, ox_oy, maximize=True)
            return step_toward((sx, sy), target)
        return [1, 1] if grid_w and grid_h else [0, 0]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        target = best_target(targets, (sx, sy), maximize=False)
        if target is not None:
            return step_toward((sx, sy), target)
        if ox_oy is not None:
            return step_toward((sx, sy), ox_oy)
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_target(resources, (sx, sy), maximize=False)
    if target is not None:
        return step_toward((sx, sy), target)

    if ox_oy is not None:
        return step_toward((sx, sy), ox_oy)

    grid_w = sg("grid_width", 0)
    grid_h = sg("grid_height", 0)
    if grid_w and grid_h:
        return step_toward((sx, sy), (grid_w // 2, grid_h // 2))
    return [0, 0]

